cat > render.js <<'EOF'
const puppeteer=require('puppeteer-core'); const fs=require('fs'); const path=require('path');
const [,, start, end, outDir, step='1'] = process.argv;
const FPS=30;
(async()=>{
  const b=await puppeteer.launch({executablePath:'/usr/bin/google-chrome',headless:'new',
    args:['--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox','--hide-scrollbars','--force-device-scale-factor=1']});
  const p=await b.newPage(); await p.setViewport({width:1920,height:1080});
  p.on('pageerror',e=>console.error('PAGEERR',e.message)); p.on('console',m=>console.log('console',m.text()));
  await p.goto('file://'+path.resolve(__dirname,'index.html'));
  const audio=fs.readFileSync(path.resolve(__dirname,'../frames.json'),'utf8');
  await p.evaluate(a=>window.setAudio(JSON.parse(a)),audio);
  await p.evaluate(()=>document.fonts.ready);
  await p.evaluate(()=>{ for(const f of ['900 150px "Noto Sans Mono CJK SC"','400 56px "Noto Serif CJK SC"','300 46px "Noto Serif CJK SC"']) document.fonts.load(f,'信号ABC'); });
  await new Promise(r=>setTimeout(r,300));
  for(let i=+start;i<+end;i+=+step){
    const t0=Date.now();
    await p.evaluate(t=>window.renderFrame(t), i/FPS);
    await p.screenshot({path:`${outDir}/f${String(i).padStart(5,'0')}.jpg`,type:'jpeg',quality:93});
    if(i===+start) console.log('frame',i,Date.now()-t0,'ms');
  }
  await b.close();
})();
EOF
